const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"description\" content=\"Voyager is a private AI workspace for coding, study, research, and everyday work.\" />\n  <meta name=\"theme-color\" content=\"#f7f6f2\" />\n  <title>Voyager AI</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400;500&family=Manrope:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='14' fill='%23201f1d'/%3E%3Cpath d='M14 17l18 35 18-35-18 9z' fill='%23f7f6f2'/%3E%3Ccircle cx='32' cy='18' r='5' fill='%23cb5b53'/%3E%3C/svg%3E\" />\n  <style>\n    :root{--paper:#f7f6f2;--paper-2:#efede7;--surface:#fff;--ink:#232220;--muted:#77736d;--line:#dedbd4;--line-2:#cbc6bd;--red:#be514b;--red-soft:#f4e7e4;--green:#4d725f;--sidebar:#f1efe9;--code:#201f1d;--code-ink:#f5f2ea;--shadow:0 18px 60px rgba(35,34,32,.08);--radius:16px;color-scheme:light}\n    :root[data-theme=\"dark\"]{--paper:#151515;--paper-2:#242321;--surface:#1d1c1b;--ink:#f3f0e9;--muted:#aaa49b;--line:#363431;--line-2:#4b4843;--red:#e2746c;--red-soft:#3a2423;--green:#88b89e;--sidebar:#1a1918;--code:#0d0d0d;--code-ink:#f5f2ea;--shadow:0 18px 60px rgba(0,0,0,.35);color-scheme:dark}\n    *{box-sizing:border-box}\n    html,body{margin:0;height:100%;background:var(--paper);color:var(--ink);font-family:Manrope,system-ui,sans-serif}\n    button,input,textarea{font:inherit}\n    button{color:inherit}\n    .mono{font-family:\"DM Mono\",ui-monospace,monospace}\n    .app{height:100dvh;display:grid;grid-template-columns:272px minmax(0,1fr);overflow:hidden}\n    .sidebar{background:var(--sidebar);border-right:1px solid var(--line);padding:18px 14px 14px;display:flex;flex-direction:column;min-width:0}\n    .brand{height:44px;display:flex;align-items:center;gap:10px;padding:0 10px;margin-bottom:12px}\n    .brand-mark{width:27px;height:27px;background:var(--ink);border-radius:8px;display:grid;place-items:center;position:relative}\n    .brand-mark:before{content:\"\";width:13px;height:15px;background:var(--paper);clip-path:polygon(0 0,50% 100%,100% 0,50% 24%)}\n    .brand-mark:after{content:\"\";position:absolute;width:5px;height:5px;border-radius:50%;background:var(--red);top:5px}\n    .brand strong{font-size:16px;letter-spacing:-.02em}\n    .brand small{font-size:10px;color:var(--red);border:1px solid #dfbbb7;background:#f9eeec;padding:2px 5px;border-radius:999px;margin-left:auto}\n    .new-chat{height:44px;border:1px solid var(--line-2);background:var(--paper);border-radius:12px;display:flex;align-items:center;gap:10px;padding:0 13px;cursor:pointer;box-shadow:0 2px 8px rgba(35,34,32,.03)}\n    .new-chat:hover{border-color:var(--muted);background:var(--surface)}\n    .new-chat span:last-child{margin-left:auto;color:var(--muted);font-size:12px}\n    .nav{display:grid;gap:3px;margin-top:13px}\n    .nav-btn{border:0;background:transparent;border-radius:10px;padding:9px 11px;display:flex;align-items:center;gap:11px;text-align:left;cursor:pointer;font-size:14px}\n    .nav-btn:hover,.nav-btn.active{background:var(--paper-2)}.nav-btn.active{font-weight:600}\n    .nav-icon{width:18px;text-align:center;color:var(--muted)}\n    .section-label{font:500 11px \"DM Mono\",monospace;color:#948f88;letter-spacing:.09em;text-transform:uppercase;padding:20px 11px 8px}\n    .history{overflow:auto;min-height:0}\n    .history button{width:100%;border:0;background:transparent;border-radius:9px;padding:8px 11px;text-align:left;color:#57534e;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer}\n    .history button:hover{background:var(--paper-2);color:var(--ink)}\n    .sidebar-foot{margin-top:auto;border-top:1px solid var(--line);padding-top:11px}\n    .profile{display:flex;align-items:center;gap:10px;padding:9px;border-radius:11px;cursor:pointer}\n    .profile:hover{background:#e7e4dd}\n    .avatar{width:30px;height:30px;border-radius:9px;background:var(--ink);color:white;display:grid;place-items:center;font-size:12px;font-weight:700}\n    .profile-copy{font-size:12px;line-height:1.35}.profile-copy span{display:block;color:var(--muted);font-size:11px}\n    .main{min-width:0;display:flex;flex-direction:column;height:100%;position:relative;background:var(--paper)}\n    .topbar{height:64px;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 24px;gap:10px;background:color-mix(in srgb,var(--paper) 90%,transparent);backdrop-filter:blur(12px);z-index:2}\n    .mobile-menu{display:none!important;border:0;background:transparent;font-size:21px}\n    .model-picker{position:relative}\n    .model-btn{border:0;background:transparent;border-radius:10px;padding:8px 10px;display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:650}\n    .model-btn:hover{background:var(--paper-2)}\n    .model-dot{width:7px;height:7px;border-radius:50%;background:var(--red);box-shadow:0 0 0 3px var(--red-soft)}\n    .chev{font-size:11px;color:var(--muted)}\n    .top-actions{margin-left:auto;display:flex;align-items:center;gap:6px}\n    .icon-btn{width:38px;height:38px;border:1px solid transparent;background:transparent;border-radius:10px;display:grid;place-items:center;cursor:pointer;font-size:17px}\n    .icon-btn:hover{background:var(--paper-2);border-color:var(--line)}\n    .connect-btn{height:38px;border:1px solid var(--line-2);background:var(--surface);border-radius:10px;padding:0 13px;cursor:pointer;font:500 12px \"DM Mono\",monospace}\n    .connect-btn:hover{border-color:var(--ink)}\n    .model-menu{display:none;position:absolute;top:45px;left:0;width:330px;background:var(--surface);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);padding:8px;z-index:10}\n    .model-menu.open{display:block}\n    .model-option{width:100%;border:0;background:transparent;border-radius:10px;padding:11px;display:grid;grid-template-columns:1fr auto;gap:3px 12px;text-align:left;cursor:pointer}\n    .model-option:hover,.model-option.selected{background:var(--paper-2)}\n    .model-option strong{font-size:13px}.model-option small{color:var(--muted);font-size:11px;grid-column:1}.tag{font:500 10px \"DM Mono\",monospace;color:var(--red);background:var(--red-soft);padding:3px 6px;border-radius:6px}\n    .workspace{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;scroll-behavior:smooth;display:flex;justify-content:center}\n    .chat{width:min(840px,calc(100% - 40px));padding:56px 0 44px;min-height:min-content}\n    .welcome{display:block}\n    .eyebrow{font:500 11px \"DM Mono\",monospace;color:var(--red);letter-spacing:.13em;text-transform:uppercase;margin-bottom:15px}\n    h1{font:500 clamp(34px,5vw,54px)/1.02 \"DM Mono\",monospace;letter-spacing:-.05em;margin:0;max-width:700px}\n    .intro{font:400 16px/1.65 \"DM Mono\",monospace;color:#67625c;max-width:680px;margin:20px 0 32px}\n    .modes{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:30px}\n    .mode{min-height:116px;border:1px solid var(--line);background:color-mix(in srgb,var(--surface) 65%,transparent);border-radius:14px;padding:15px;text-align:left;cursor:pointer;transition:.18s ease}\n    .mode:hover{transform:translateY(-2px);border-color:var(--muted);background:var(--surface);box-shadow:0 8px 24px rgba(35,34,32,.05)}\n    .mode-icon{color:var(--red);font-size:18px}.mode strong{display:block;margin:16px 0 5px;font-size:14px}.mode span{display:block;color:var(--muted);font:400 11px/1.45 \"DM Mono\",monospace}\n    .dayline{display:flex;align-items:center;gap:12px;color:#8c867e;font:400 11px \"DM Mono\",monospace;text-transform:uppercase;letter-spacing:.08em}\n    .dayline:before,.dayline:after{content:\"\";height:1px;background:var(--line);flex:1}\n    .message{display:none;margin:0 auto 26px}.message.visible{display:flex;gap:14px}\n    .message.user{justify-content:flex-end}.message.user .bubble{background:var(--paper-2);border:1px solid var(--line);max-width:75%;padding:14px 16px;border-radius:16px 16px 4px 16px}\n    .message.assistant .assistant-mark{width:27px;height:27px;flex:0 0 auto;margin-top:2px;background:var(--ink);color:white;border-radius:8px;display:grid;place-items:center;font:600 11px \"DM Mono\",monospace}\n    .message.assistant .bubble{font-size:15px;line-height:1.7;max-width:720px;min-width:0;overflow-wrap:anywhere}.message.assistant .meta{font:400 11px \"DM Mono\",monospace;color:var(--muted);margin-top:9px}\n    .markdown>:first-child{margin-top:0}.markdown>:last-child{margin-bottom:0}.markdown p{margin:0 0 14px}.markdown h1,.markdown h2,.markdown h3{font-family:\"DM Mono\",monospace;letter-spacing:-.025em;line-height:1.25;margin:24px 0 10px}.markdown h1{font-size:24px}.markdown h2{font-size:20px}.markdown h3{font-size:17px}.markdown ul,.markdown ol{margin:8px 0 16px;padding-left:24px}.markdown li{margin:5px 0}.markdown blockquote{margin:14px 0;padding:2px 0 2px 14px;border-left:3px solid var(--red);color:var(--muted)}.markdown a{color:var(--red)}.markdown code:not(pre code){font:500 .9em \"DM Mono\",monospace;background:var(--paper-2);border:1px solid var(--line);border-radius:5px;padding:2px 5px}.code-block{margin:16px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--code);color:var(--code-ink)}.code-head{height:36px;padding:0 12px;display:flex;align-items:center;border-bottom:1px solid #363432;color:#aaa49b;font:500 11px \"DM Mono\",monospace}.copy-code{margin-left:auto;border:0;background:transparent;color:#ddd7cc;cursor:pointer;font:inherit}.copy-code:hover{color:#fff}.code-block pre{margin:0;padding:16px;overflow:auto;white-space:pre;tab-size:2}.code-block code{font:400 13px/1.65 \"DM Mono\",monospace}.composer-wrap{position:relative;flex:0 0 auto;padding:14px 24px 18px;background:var(--paper);border-top:1px solid var(--line)}\n    .composer{width:min(840px,100%);margin:auto;background:var(--surface);border:1px solid var(--line-2);border-radius:18px;box-shadow:0 12px 40px rgba(35,34,32,.09);padding:8px}\n    .drop-note{display:none;padding:10px 12px;border:1px dashed var(--red);border-radius:12px;background:var(--red-soft);color:#8b3d38;font:500 12px \"DM Mono\",monospace;margin-bottom:7px}\n    .composer.dragging .drop-note{display:block}\n    .attachments{display:flex;gap:7px;overflow:auto;padding:0 4px}.file-chip{display:flex;align-items:center;gap:7px;border:1px solid var(--line);background:var(--paper);border-radius:10px;padding:7px 9px;font-size:11px;white-space:nowrap}.file-chip button{border:0;background:transparent;color:var(--muted);cursor:pointer;padding:0}\n    textarea{width:100%;min-height:58px;max-height:160px;resize:none;border:0;outline:0;padding:11px 12px 5px;color:var(--ink);background:transparent;font-size:15px;line-height:1.5}\n    textarea::placeholder{color:#9b968e}\n    .composer-foot{display:flex;align-items:center;padding:3px 4px 2px;gap:5px;min-width:0}\n    .tool-btn{height:34px;border:0;background:transparent;border-radius:9px;padding:0 9px;display:flex;align-items:center;gap:7px;color:#6f6a63;font-size:12px;cursor:pointer}\n    .tool-btn:hover{background:var(--paper-2);color:var(--ink)}\n    .send{margin-left:auto;height:40px;min-width:88px;flex:0 0 auto;border:0;border-radius:11px;padding:0 15px;background:var(--ink);color:var(--paper);display:flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;font-weight:700}.send:hover{background:var(--red);color:#fff}.send:disabled{opacity:.55;cursor:wait}\n    .hint{text-align:center;color:#9b968e;font:400 10px \"DM Mono\",monospace;margin-top:9px}\n    .modal-backdrop{position:fixed;inset:0;background:rgba(28,27,25,.3);display:none;place-items:center;padding:20px;z-index:30;backdrop-filter:blur(3px)}\n    .modal-backdrop.open{display:grid}.modal{width:min(560px,100%);background:var(--paper);border:1px solid var(--line-2);border-radius:18px;box-shadow:var(--shadow);padding:22px}.modal-head{display:flex;align-items:flex-start;gap:14px}.modal h2{font:500 24px \"DM Mono\",monospace;margin:0}.modal p{color:var(--muted);font-size:13px;line-height:1.6}.modal-head button{margin-left:auto;border:0;background:transparent;color:var(--ink);font-size:20px;cursor:pointer}.provider{border:1px solid var(--line);background:var(--surface);border-radius:13px;padding:14px;margin-top:12px;display:flex;align-items:center;gap:12px}.provider-logo{width:38px;height:38px;border-radius:10px;background:var(--paper-2);display:grid;place-items:center;font-weight:700}.provider-copy{font-size:13px}.provider-copy span{display:block;color:var(--muted);font-size:11px;margin-top:3px}.provider button{margin-left:auto;border:1px solid var(--line-2);background:var(--paper);color:var(--ink);padding:8px 11px;border-radius:9px;font-size:12px;cursor:pointer}.provider button:hover{border-color:var(--ink)}\n    .search-box{display:flex;gap:8px;margin-top:16px}.search-box input{flex:1;min-width:0;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);border-radius:10px;padding:11px 12px;outline:0}.search-results{display:grid;gap:6px;margin-top:12px;max-height:280px;overflow:auto}.search-result{border:1px solid var(--line);background:var(--surface);color:var(--ink);border-radius:10px;padding:10px 12px;text-align:left;cursor:pointer}.search-result:hover{border-color:var(--muted)}\n    .toast{position:fixed;right:20px;bottom:20px;background:var(--ink);color:white;border-radius:12px;padding:12px 15px;font-size:12px;box-shadow:var(--shadow);transform:translateY(80px);opacity:0;transition:.25s;z-index:50}.toast.show{transform:translateY(0);opacity:1}\n    @media(max-width:820px){.app{grid-template-columns:1fr}.sidebar{position:fixed;inset:0 auto 0 0;width:280px;z-index:20;transform:translateX(-100%);transition:.22s;box-shadow:var(--shadow)}.sidebar.open{transform:translateX(0)}.mobile-menu{display:grid!important}.topbar{padding:0 14px}.connect-btn{display:none}.chat{width:min(100% - 28px,720px);padding-top:36px}.modes{grid-template-columns:repeat(2,1fr)}.composer-wrap{padding-left:12px;padding-right:12px}.tool-btn span:not(:first-child){display:none}}\n    @media(max-width:480px){.modes{grid-template-columns:1fr 1fr}.mode{min-height:105px;padding:12px}.connect-btn{display:none}.top-actions{gap:2px}h1{font-size:36px}.intro{font-size:14px}.chat{padding-bottom:30px}.model-btn{font-size:13px}.model-menu{width:min(330px,calc(100vw - 30px));left:-44px}.composer-wrap{padding:10px 10px 12px}.send{min-width:78px;padding:0 12px}.markdown h1{font-size:21px}.code-block pre{padding:13px}}\n    @media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n  </style>\n</head>\n<body>\n  <div class=\"app\">\n    <aside class=\"sidebar\" id=\"sidebar\">\n      <div class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\"></span><strong class=\"mono\">Voyager AI</strong><small class=\"mono\">private</small></div>\n      <button class=\"new-chat\" id=\"newChat\"><span>＋</span><strong>New conversation</strong><span class=\"mono\">⌘ K</span></button>\n      <nav class=\"nav\" aria-label=\"Main navigation\">\n        <button class=\"nav-btn active\" data-workspace=\"chat\"><span class=\"nav-icon\">◎</span>Chat</button>\n        <button class=\"nav-btn\" data-workspace=\"research\"><span class=\"nav-icon\">⌕</span>Deep research</button>\n        <button class=\"nav-btn\" data-workspace=\"documents\"><span class=\"nav-icon\">▧</span>Documents</button>\n        <button class=\"nav-btn\" data-workspace=\"agents\"><span class=\"nav-icon\">✦</span>Agents</button>\n      </nav>\n      <div class=\"section-label\">Your workspace</div>\n      <nav class=\"nav\">\n        <button class=\"nav-btn\" data-connect=\"Calendar\"><span class=\"nav-icon\">□</span>Calendar</button>\n        <button class=\"nav-btn\" data-connect=\"Mail\"><span class=\"nav-icon\">◇</span>Mail</button>\n        <button class=\"nav-btn\" data-workspace=\"tasks\"><span class=\"nav-icon\">✓</span>Tasks</button>\n      </nav>\n      <div class=\"section-label\">Recent</div>\n      <div class=\"history\" id=\"history\">\n        <button>Build a Python study plan</button><button>Review portfolio component</button><button>Summarize lecture notes</button><button>Plan next week</button>\n      </div>\n      <div class=\"sidebar-foot\"><div class=\"profile\" id=\"settings\"><div class=\"avatar\">Y</div><div class=\"profile-copy\">Your workspace<span>Models & integrations</span></div><span style=\"margin-left:auto;color:var(--muted)\">···</span></div></div>\n    </aside>\n    <main class=\"main\">\n      <header class=\"topbar\">\n        <button class=\"mobile-menu icon-btn\" id=\"mobileMenu\" aria-label=\"Open menu\">☰</button>\n        <div class=\"model-picker\">\n          <button class=\"model-btn\" id=\"modelButton\" aria-haspopup=\"listbox\" aria-expanded=\"false\"><span class=\"model-dot\"></span><span id=\"modelName\">Nemotron 3 Ultra</span><span class=\"chev\">⌄</span></button>\n          <div class=\"model-menu\" id=\"modelMenu\" role=\"listbox\">\n            <button class=\"model-option\" data-model=\"Nemotron 3.5 Lightning\"><strong>Nemotron 3.5 Lightning</strong><span class=\"tag\">fast</span><small>Everyday work · coding · agents</small></button>\n            <button class=\"model-option selected\" data-model=\"Nemotron 3 Ultra\"><strong>Nemotron 3 Ultra</strong><span class=\"tag\">deep</span><small>Complex reasoning · long documents · planning</small></button>\n            <button class=\"model-option\" data-model=\"Nemotron 3 Nano Omni\"><strong>Nemotron 3 Nano Omni</strong><span class=\"tag\">omni</span><small>Images, audio, video, OCR, and transcription</small></button>\n            <button class=\"model-option\" data-model=\"Llama 3.2 Vision\"><strong>Llama 3.2 Vision</strong><span class=\"tag\">vision</span><small>Image reasoning and visual documents</small></button>\n          </div>\n        </div>\n        <div class=\"top-actions\"><button class=\"icon-btn\" id=\"searchButton\" aria-label=\"Search conversations\">⌕</button><button class=\"icon-btn\" id=\"shareButton\" aria-label=\"Copy conversation\">↗</button><button class=\"icon-btn\" id=\"themeToggle\" aria-label=\"Use dark mode\" title=\"Toggle dark mode\">◐</button><button class=\"connect-btn\" id=\"connectTop\">Connect tools</button></div>\n      </header>\n      <div class=\"workspace\" id=\"workspace\">\n        <section class=\"chat\" aria-live=\"polite\">\n          <div class=\"welcome\" id=\"welcome\">\n            <div class=\"eyebrow\">Your private intelligence workspace</div>\n            <h1>What are we working on?</h1>\n            <p class=\"intro\">Code, study, plan, or bring your own files. Voyager routes each task to the right model while keeping you in control.</p>\n            <div class=\"modes\">\n              <button class=\"mode\" data-prompt=\"Help me build and debug a coding project.\"><span class=\"mode-icon\">&lt;/&gt;</span><strong>Build & code</strong><span>Write, review, debug</span></button>\n              <button class=\"mode\" data-prompt=\"Help me study this topic with a clear lesson and a quiz.\"><span class=\"mode-icon\">◒</span><strong>Study</strong><span>Learn, practice, quiz</span></button>\n              <button class=\"mode\" data-prompt=\"Research this topic deeply and organize the findings.\"><span class=\"mode-icon\">⌕</span><strong>Research</strong><span>Find, compare, synthesize</span></button>\n              <button class=\"mode\" data-prompt=\"Help me plan my day and organize my priorities.\"><span class=\"mode-icon\">✓</span><strong>Plan my day</strong><span>Calendar, mail, tasks</span></button>\n            </div>\n            <div class=\"dayline\">Ready when you are</div>\n          </div>\n          <div class=\"message user\" id=\"userMessage\"><div class=\"bubble\" id=\"userBubble\"></div></div>\n          <div class=\"message assistant\" id=\"assistantMessage\"><div class=\"assistant-mark\">V</div><div class=\"bubble\"><div id=\"assistantText\"></div><div class=\"meta\" id=\"assistantMeta\"></div></div></div>\n        </section>\n      </div>\n      <div class=\"composer-wrap\">\n        <div class=\"composer\" id=\"composer\">\n          <div class=\"drop-note\">Drop files here — documents, code, images, audio, or video</div>\n          <div class=\"attachments\" id=\"attachments\"></div>\n          <textarea id=\"prompt\" rows=\"1\" placeholder=\"Message Voyager…\" aria-label=\"Message Voyager\"></textarea>\n          <div class=\"composer-foot\">\n            <button class=\"tool-btn\" id=\"attach\"><span style=\"font-size:19px\">＋</span><span>Add files</span></button>\n            <input id=\"fileInput\" type=\"file\" hidden multiple accept=\".pdf,.doc,.docx,.txt,.md,.csv,.json,.js,.ts,.tsx,.jsx,.py,.java,.c,.cpp,.html,.css,image/*,audio/*,video/*\" />\n            <button class=\"tool-btn\" id=\"voiceButton\"><span style=\"font-size:16px\">◉</span><span>Voice</span></button>\n            <button class=\"tool-btn\" id=\"toolsButton\"><span style=\"font-size:16px\">✦</span><span>Tools</span></button>\n            <button class=\"send\" id=\"send\" aria-label=\"Send message\"><span>Send</span><span aria-hidden=\"true\">↑</span></button>\n          </div>\n        </div>\n        <div class=\"hint\">Voyager can make mistakes. Review important work.</div>\n      </div>\n    </main>\n  </div>\n\n  <div class=\"modal-backdrop\" id=\"modalBackdrop\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modalTitle\">\n    <div class=\"modal\">\n      <div class=\"modal-head\"><div><div class=\"eyebrow\" style=\"margin-bottom:7px\">Workspace setup</div><h2 id=\"modalTitle\">Connect your tools</h2></div><button id=\"closeModal\" aria-label=\"Close\">×</button></div>\n      <p>Bring your day-to-day work into one place. Connections are only activated after you approve access.</p>\n      <div class=\"provider\"><div class=\"provider-logo\" style=\"color:#4285f4\">G</div><div class=\"provider-copy\">Google Workspace<span>Gmail, Calendar, Drive, Docs</span></div><button data-provider=\"Google Workspace\">Connect</button></div>\n      <div class=\"provider\"><div class=\"provider-logo\" style=\"color:#1675e0\">M</div><div class=\"provider-copy\">Microsoft 365<span>Outlook, Calendar, OneDrive</span></div><button data-provider=\"Microsoft 365\">Connect</button></div>\n      <div class=\"provider\"><div class=\"provider-logo\" style=\"color:#76b900\">N</div><div class=\"provider-copy\">NVIDIA NIM<span>Nemotron API endpoint</span></div><button data-provider=\"NVIDIA NIM\">Configure</button></div>\n      <p class=\"mono\" style=\"font-size:10px;margin-bottom:0\">Live connections require your account authorization or API credentials.</p>\n    </div>\n  </div>\n  <div class=\"modal-backdrop\" id=\"searchBackdrop\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"searchTitle\">\n    <div class=\"modal\">\n      <div class=\"modal-head\"><div><div class=\"eyebrow\" style=\"margin-bottom:7px\">Find your work</div><h2 id=\"searchTitle\">Search conversations</h2></div><button id=\"closeSearch\" aria-label=\"Close search\">×</button></div>\n      <div class=\"search-box\"><input id=\"searchInput\" type=\"search\" placeholder=\"Search recent prompts…\" aria-label=\"Search recent prompts\" /></div>\n      <div class=\"search-results\" id=\"searchResults\"></div>\n    </div>\n  </div>\n  <div class=\"toast\" id=\"toast\"></div>\n\n  <script>\n    (() => {\n      const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];\n      const prompt=$('#prompt'), composer=$('#composer'), files=[], conversation=[];\n      const workspaceModes={\n        chat:{eyebrow:'Your private intelligence workspace',title:'What are we working on?',intro:'Code, study, plan, or bring your own files. Voyager routes each task to the right model while keeping you in control.',prompt:'',model:'Nemotron 3 Ultra'},\n        research:{eyebrow:'Deep research',title:'Investigate a question',intro:'Define the question, evidence standard, and output you need. Voyager will structure the investigation and clearly separate evidence from inference.',prompt:'Research this topic deeply. Compare reliable sources, note uncertainty, and organize the findings with citations I can verify: ',model:'Nemotron 3 Ultra'},\n        documents:{eyebrow:'Document workspace',title:'Read, compare, and transform files',intro:'Attach documents or code, then ask for a summary, extraction, comparison, rewrite, or review.',prompt:'Review the attached document and give me a structured summary with key findings and action items.',model:'Nemotron 3 Nano Omni'},\n        agents:{eyebrow:'Agent workspace',title:'Plan a multi-step task',intro:'Describe the outcome and constraints. Voyager will create a practical plan, work through the steps, and identify where approval is needed.',prompt:'Act as a careful project agent. Break this goal into steps, identify dependencies and risks, then help me execute it: ',model:'Nemotron 3 Ultra'},\n        tasks:{eyebrow:'Task workspace',title:'Turn work into a clear plan',intro:'Capture an objective, deadline, or backlog and turn it into prioritized, concrete next actions.',prompt:'Turn the following into a prioritized task plan with owners, dependencies, and next actions: ',model:'Nemotron 3 Ultra'}\n      };\n\n      function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2600)}\n      function openModal(title='Connect your tools'){$('#modalTitle').textContent=title;$('#modalBackdrop').classList.add('open')}\n      function closeModal(){$('#modalBackdrop').classList.remove('open')}\n      function scrollChat(){requestAnimationFrame(()=>$('#workspace').scrollTo({top:$('#workspace').scrollHeight,behavior:'smooth'}))}\n      function setModel(name){const option=$$('.model-option').find(o=>o.dataset.model===name);if(option&&!option.classList.contains('selected'))option.click()}\n      function setPrompt(value){prompt.value=value;prompt.dispatchEvent(new Event('input'));prompt.focus()}\n      function activateWorkspace(name){const mode=workspaceModes[name]||workspaceModes.chat;$$('[data-workspace]').forEach(b=>b.classList.toggle('active',b.dataset.workspace===name));$('#welcome').style.display='block';$('.eyebrow').textContent=mode.eyebrow;$('h1').textContent=mode.title;$('.intro').textContent=mode.intro;setModel(mode.model);setPrompt(mode.prompt);$('#sidebar').classList.remove('open');if(name==='documents')toast('Attach files below, then ask what you need')}\n\n      function escapeHtml(value){return String(value).replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[ch]))}\n      function inlineMarkdown(value){let text=escapeHtml(value);text=text.replace(/`([^`]+)`/g,'<code>$1</code>');text=text.replace(/\\*\\*([^*]+)\\*\\*/g,'<strong>$1</strong>');text=text.replace(/__([^_]+)__/g,'<strong>$1</strong>');text=text.replace(/\\*([^*]+)\\*/g,'<em>$1</em>');text=text.replace(/\\[([^\\]]+)\\]\\((https?:\\/\\/[^\\s)]+)\\)/g,'<a href=\"$2\" target=\"_blank\" rel=\"noopener noreferrer\">$1</a>');return text}\n      function renderMarkdown(source){const lines=String(source||'').replace(/\\r\\n?/g,'\\n').split('\\n');let html='',code=[],lang='',list='';const closeList=()=>{if(list){html+=`</${list}>`;list=''}};const closeCode=()=>{const body=escapeHtml(code.join('\\n'));html+=`<div class=\"code-block\"><div class=\"code-head\"><span>${escapeHtml(lang||'code')}</span><button class=\"copy-code\" type=\"button\">Copy</button></div><pre><code>${body}</code></pre></div>`;code=[];lang=''};for(const line of lines){const fence=line.match(/^```\\s*([\\w.+-]*)/);if(fence){if(code.length||lang){closeCode()}else{closeList();lang=fence[1]||'code';code=[]}continue}if(lang){code.push(line);continue}const heading=line.match(/^(#{1,3})\\s+(.+)/);if(heading){closeList();html+=`<h${heading[1].length}>${inlineMarkdown(heading[2])}</h${heading[1].length}>`;continue}const bullet=line.match(/^\\s*[-*]\\s+(.+)/);const ordered=line.match(/^\\s*\\d+[.)]\\s+(.+)/);if(bullet||ordered){const next=ordered?'ol':'ul';if(list!==next){closeList();html+=`<${next}>`;list=next}html+=`<li>${inlineMarkdown((bullet||ordered)[1])}</li>`;continue}closeList();if(/^>\\s?/.test(line)){html+=`<blockquote>${inlineMarkdown(line.replace(/^>\\s?/,''))}</blockquote>`}else if(line.trim()){html+=`<p>${inlineMarkdown(line)}</p>`}}if(lang)closeCode();closeList();return html||'<p></p>'}\n\n      function getRecents(){try{return JSON.parse(localStorage.getItem('voyager-recents')||'[]')}catch{return[]}}\n      function saveRecent(text){if(!text)return;const items=[{text:text.slice(0,180),at:Date.now()},...getRecents().filter(x=>x.text!==text)].slice(0,12);localStorage.setItem('voyager-recents',JSON.stringify(items));renderHistory()}\n      function renderHistory(){const saved=getRecents();const defaults=['Build a Python study plan','Review portfolio component','Summarize lecture notes','Plan next week'];const items=saved.length?saved.map(x=>x.text):defaults;$('#history').innerHTML='';items.forEach(text=>{const button=document.createElement('button');button.textContent=text;button.onclick=()=>setPrompt(text);$('#history').appendChild(button)})}\n\n      $('#connectTop').onclick=()=>openModal();$('#settings').onclick=()=>openModal('Models & integrations');$('#closeModal').onclick=closeModal;\n      $('#modalBackdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal()});\n      $$('[data-connect]').forEach(b=>b.onclick=()=>openModal(`Connect ${b.dataset.connect}`));\n      $$('.provider button').forEach(b=>b.onclick=()=>toast(b.dataset.provider==='NVIDIA NIM'?'NVIDIA NIM is configured securely':'This connection needs OAuth approval before it can be enabled'));\n      $('#modelButton').onclick=()=>{const menu=$('#modelMenu'),open=menu.classList.toggle('open');$('#modelButton').setAttribute('aria-expanded',open)};\n      $$('.model-option').forEach(o=>o.onclick=()=>{$$('.model-option').forEach(x=>x.classList.remove('selected'));o.classList.add('selected');$('#modelName').textContent=o.dataset.model;$('#modelMenu').classList.remove('open');$('#modelButton').setAttribute('aria-expanded','false');toast(`Using ${o.dataset.model}`)});\n      document.addEventListener('click',e=>{if(!e.target.closest('.model-picker'))$('#modelMenu').classList.remove('open')});\n      $('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');\n      $$('[data-workspace]').forEach(b=>b.onclick=()=>activateWorkspace(b.dataset.workspace));\n\n      const savedTheme=localStorage.getItem('voyager-theme');if(savedTheme)document.documentElement.dataset.theme=savedTheme;\n      function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark';$('#themeToggle').textContent=dark?'☀':'◐';$('#themeToggle').setAttribute('aria-label',dark?'Use light mode':'Use dark mode');document.querySelector('meta[name=\"theme-color\"]').content=dark?'#151515':'#f7f6f2'}\n      $('#themeToggle').onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('voyager-theme',next);updateThemeButton()};updateThemeButton();\n\n      function resetChat(){activateWorkspace('chat');$('#userMessage').classList.remove('visible');$('#assistantMessage').classList.remove('visible');prompt.value='';files.splice(0);conversation.splice(0);renderFiles();prompt.focus()}\n      $('#newChat').onclick=resetChat;\n      function addFiles(list){const accepted=[...list].filter(f=>{if(f.size>5*1024*1024){toast(`${f.name} is over the 5 MB preview limit`);return false}return true});accepted.forEach(f=>{if(!files.some(x=>x.name===f.name&&x.size===f.size))files.push(f)});renderFiles();if(accepted.some(f=>/^(image|audio|video)\\//.test(f.type)))setModel('Nemotron 3 Nano Omni');if(accepted.length)toast(`${accepted.length} file${accepted.length>1?'s':''} attached`)}\n      function renderFiles(){$('#attachments').innerHTML='';files.forEach((f,i)=>{const chip=document.createElement('div');chip.className='file-chip';const type=f.type.startsWith('image/')?'▧':f.type.startsWith('audio/')?'♪':f.type.startsWith('video/')?'▷':'▤';chip.innerHTML=`<span>${type}</span><span>${escapeHtml(f.name)}</span><button aria-label=\"Remove ${escapeHtml(f.name)}\">×</button>`;chip.querySelector('button').onclick=()=>{files.splice(i,1);renderFiles()};$('#attachments').appendChild(chip)})}\n      $('#attach').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=e=>addFiles(e.target.files);\n      ['dragenter','dragover'].forEach(evt=>composer.addEventListener(evt,e=>{e.preventDefault();composer.classList.add('dragging')}));\n      ['dragleave','drop'].forEach(evt=>composer.addEventListener(evt,e=>{e.preventDefault();composer.classList.remove('dragging')}));composer.addEventListener('drop',e=>addFiles(e.dataTransfer.files));\n      prompt.addEventListener('input',()=>{prompt.style.height='auto';prompt.style.height=Math.min(prompt.scrollHeight,160)+'px'});\n      prompt.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});\n      $$('.mode').forEach(m=>m.onclick=()=>setPrompt(m.dataset.prompt));\n\n      const searchBackdrop=$('#searchBackdrop');function searchItems(query=''){const q=query.trim().toLowerCase();const items=getRecents().map(x=>x.text);$('#searchResults').innerHTML='';const matches=(items.length?items:['No saved conversations yet']).filter(x=>!q||x.toLowerCase().includes(q));matches.forEach(text=>{const button=document.createElement('button');button.className='search-result';button.textContent=text;button.onclick=()=>{if(items.length)setPrompt(text);searchBackdrop.classList.remove('open')};$('#searchResults').appendChild(button)})}\n      $('#searchButton').onclick=()=>{searchBackdrop.classList.add('open');searchItems();setTimeout(()=>$('#searchInput').focus(),0)};$('#closeSearch').onclick=()=>searchBackdrop.classList.remove('open');$('#searchInput').oninput=e=>searchItems(e.target.value);searchBackdrop.addEventListener('click',e=>{if(e.target===e.currentTarget)searchBackdrop.classList.remove('open')});\n      $('#shareButton').onclick=async()=>{if(!conversation.length){toast('Start a conversation before sharing');return}const text=conversation.map(m=>`## ${m.role==='user'?'You':'Voyager'}\\n\\n${typeof m.content==='string'?m.content:'[Message with attachments]'}`).join('\\n\\n');try{await navigator.clipboard.writeText(text);toast('Conversation copied to clipboard')}catch{toast('Clipboard access is unavailable in this browser')}};\n      $('#toolsButton').onclick=()=>openModal('Tools & integrations');\n      let recognition;$('#voiceButton').onclick=()=>{const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Voice input is not supported in this browser');return}if(recognition){recognition.stop();return}recognition=new SpeechRecognition();recognition.continuous=false;recognition.interimResults=false;recognition.onresult=e=>setPrompt(`${prompt.value}${prompt.value?' ':''}${e.results[0][0].transcript}`);recognition.onerror=()=>toast('Voice input could not start');recognition.onend=()=>{recognition=null;$('#voiceButton').classList.remove('active')};recognition.start();$('#voiceButton').classList.add('active');toast('Listening…')};\n      $('#assistantText').addEventListener('click',async e=>{const button=e.target.closest('.copy-code');if(!button)return;const code=button.closest('.code-block').querySelector('code').textContent;try{await navigator.clipboard.writeText(code);button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1400)}catch{toast('Clipboard access is unavailable')}});\n\n      function readDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}\n      function readText(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=reject;reader.readAsText(file)})}\n      async function filePart(file){const kind=file.type.split('/')[0];if(['image','audio','video'].includes(kind)){const url=await readDataUrl(file);return{type:`${kind}_url`,[`${kind}_url`]:{url},name:file.name}}const textTypes=/\\.(txt|md|csv|json|js|jsx|ts|tsx|py|java|c|cpp|h|html|css|xml|yaml|yml|toml|sql|sh|ps1)$/i;if(file.type.startsWith('text/')||textTypes.test(file.name)){const body=(await readText(file)).slice(0,200000);return{type:'text',text:`\\n--- Attached file: ${file.name} ---\\n${body}\\n--- End file ---`}}return{type:'text',text:`\\nAttached file metadata: ${file.name} (${file.type||'unknown type'}, ${file.size} bytes). Binary extraction for this format is not yet enabled.`}}\n      async function sendMessage(){const text=prompt.value.trim();if(!text&&!files.length)return;const pending=[...files],model=$('#modelName').textContent;$('#welcome').style.display='none';$('#userBubble').textContent=text||`Please work with ${pending.length} attached file${pending.length>1?'s':''}.`;$('#userMessage').classList.add('visible');$('#assistantText').className='';$('#assistantText').textContent='Thinking…';$('#assistantMeta').textContent='';$('#assistantMessage').classList.add('visible');prompt.value='';prompt.style.height='auto';$('#send').disabled=true;scrollChat();try{const parts=[{type:'text',text:text||'Please analyze the attached file.'},...(await Promise.all(pending.map(filePart)))];const content=parts.length===1?parts[0].text:parts;conversation.push({role:'user',content});saveRecent(text);const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model,messages:conversation.slice(-12)})});const data=await res.json().catch(()=>({error:'The AI service returned an unreadable response.'}));if(!res.ok)throw new Error(data.error||`AI request failed (${res.status})`);conversation.push({role:'assistant',content:data.content});$('#assistantText').className='markdown';$('#assistantText').innerHTML=renderMarkdown(data.content);$('#assistantMeta').textContent=`${data.model||model} · NVIDIA NIM`;files.splice(0);renderFiles()}catch(error){$('#assistantText').className='';$('#assistantText').textContent=error.message;$('#assistantMeta').textContent='Request stopped';}finally{$('#send').disabled=false;scrollChat()}}\n      $('#send').onclick=sendMessage;\n      document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();resetChat()}if(e.key==='Escape'){closeModal();searchBackdrop.classList.remove('open');$('#modelMenu').classList.remove('open');$('#sidebar').classList.remove('open')}});\n      renderHistory();setModel('Nemotron 3 Ultra');\n      if(document.modelContext?.registerTool){const lifecycle=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'start_new_conversation',title:'Start new conversation',description:'Clear the current Voyager conversation and focus the message composer.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){resetChat();return{status:'ready'}}},{signal:lifecycle.signal})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'select_ai_model',title:'Select AI model',description:'Select the active AI model in Voyager.',inputSchema:{type:'object',properties:{model:{type:'string',enum:['Nemotron 3.5 Lightning','Nemotron 3 Ultra','Nemotron 3 Nano Omni','Llama 3.2 Vision']}},required:['model'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute({model}){const option=$$('.model-option').find(o=>o.dataset.model===model);if(!option)throw new Error('Unsupported model');option.click();return{model,status:'selected'}}},{signal:lifecycle.signal})).catch(()=>{})}\n    })();\n  </script>\n</body>\n</html>\n";

const MODELS = {
  "Nemotron 3.5 Lightning": {
    id: "nvidia/nemotron-3.5-lightning-30b-a3b",
    temperature: 1,
    top_p: 0.95,
    max_tokens: 4096,
    chat_template_kwargs: { enable_thinking: false }
  },
  "Nemotron 3 Ultra": {
    id: "nvidia/nemotron-3-ultra-550b-a55b",
    temperature: 0.6,
    top_p: 0.95,
    max_tokens: 16384,
    chat_template_kwargs: { enable_thinking: true }
  },
  "Nemotron 3 Nano Omni": {
    id: "nvidia/nemotron-3-nano-omni-30b-a3b-reasoning",
    temperature: 0.6,
    top_p: 0.95,
    max_tokens: 8192,
    reasoning_budget: 4096
  },
  "Llama 3.2 Vision": {
    id: "meta/llama-3.2-90b-vision-instruct",
    temperature: 0.4,
    top_p: 0.9,
    max_tokens: 4096
  }
};

const SYSTEM = `You are Voyager, a careful personal AI workspace assistant. Help with coding, study, research, planning, and day-to-day work. Be direct, practical, and honest about uncertainty. Never claim to have sent email, changed a calendar, or modified an external system unless an approved tool confirms it.`;

const securityHeaders = {
  "content-security-policy": "default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; script-src 'self' 'unsafe-inline'; img-src 'self' data: https:; media-src 'self' data: blob:; connect-src 'self' https://integrate.api.nvidia.com; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",
  "referrer-policy": "strict-origin-when-cross-origin",
  "x-content-type-options": "nosniff",
  "x-frame-options": "DENY",
  "permissions-policy": "camera=(), geolocation=(), payment=()"
};

function json(data, status = 200, headers = {}) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", ...securityHeaders, ...headers }
  });
}

function cleanContent(content) {
  if (typeof content === "string") return content.slice(0, 250000);
  if (!Array.isArray(content)) throw new Error("Message content must be text or a supported attachment list.");
  return content.slice(0, 8).map((part) => {
    if (!part || typeof part !== "object") throw new Error("Invalid attachment part.");
    if (part.type === "text") return { type: "text", text: String(part.text || "").slice(0, 200000) };
    if (["image_url", "audio_url", "video_url"].includes(part.type)) {
      const key = part.type;
      const url = part[key]?.url;
      if (typeof url !== "string" || (!url.startsWith("data:") && !url.startsWith("https://"))) throw new Error("Attachment URL must be a data URL or HTTPS URL.");
      if (url.length > 7_500_000) throw new Error("An attachment is too large. Use files under 5 MB.");
      return { type: part.type, [key]: { url } };
    }
    throw new Error(`Unsupported attachment type: ${part.type || "unknown"}`);
  });
}

function cleanMessages(messages) {
  if (!Array.isArray(messages) || messages.length === 0 || messages.length > 12) throw new Error("Provide between 1 and 12 messages.");
  return messages.map((message) => {
    if (!message || !["user", "assistant"].includes(message.role)) throw new Error("Invalid message role.");
    return { role: message.role, content: cleanContent(message.content) };
  });
}

async function chat(request, env) {
  if (!env.NVIDIA_API_KEY) return json({ error: "NVIDIA_API_KEY is not configured yet. Add it as a deployment secret, then try again." }, 503);
  let body;
  try { body = await request.json(); } catch { return json({ error: "Request body must be valid JSON." }, 400); }
  const config = MODELS[body.model];
  if (!config) return json({ error: "Choose one of the supported NVIDIA models." }, 400);
  let messages;
  try { messages = [{ role: "system", content: SYSTEM }, ...cleanMessages(body.messages)]; }
  catch (error) { return json({ error: error.message }, 400); }

  const payload = { model: config.id, messages, stream: true, ...config };
  delete payload.id;
  let upstream;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60_000);
  try {
    upstream = await fetch("https://integrate.api.nvidia.com/v1/chat/completions", {
      method: "POST",
      headers: { "authorization": `Bearer ${env.NVIDIA_API_KEY}`, "content-type": "application/json", "accept": "text/event-stream" },
      body: JSON.stringify(payload),
      signal: controller.signal
    });
  } catch (error) {
    if (error?.name === "AbortError") return json({ error: "NVIDIA NIM took too long to respond. Try again or choose another model." }, 504);
    return json({ error: "Voyager could not reach NVIDIA NIM. Try again shortly." }, 502);
  } finally {
    clearTimeout(timeout);
  }

  const raw = await upstream.text();
  if (!upstream.ok) {
    let data;
    try { data = JSON.parse(raw); } catch { data = null; }
    const message = data?.error?.message || data?.detail || `NVIDIA NIM returned ${upstream.status}.`;
    return json({ error: String(message).slice(0, 800) }, upstream.status >= 400 && upstream.status < 600 ? upstream.status : 502);
  }
  let content = "";
  let usage = null;
  for (const line of raw.split(/\r?\n/)) {
    if (!line.startsWith("data:")) continue;
    const value = line.slice(5).trim();
    if (!value || value === "[DONE]") continue;
    try {
      const chunk = JSON.parse(value);
      content += chunk?.choices?.[0]?.delta?.content || "";
      usage = chunk?.usage || usage;
    } catch {}
  }
  if (!content) {
    try {
      const data = JSON.parse(raw);
      content = data?.choices?.[0]?.message?.content || "";
      usage = data?.usage || null;
    } catch {}
  }
  if (!content) return json({ error: "NVIDIA NIM returned an empty response." }, 502);
  return json({ content, model: config.id, usage });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === "GET" && url.pathname === "/") {
      return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8", ...securityHeaders } });
    }
    if (request.method === "GET" && url.pathname === "/api/health") {
      return json({ ok: true, configured: Boolean(env.NVIDIA_API_KEY), models: Object.keys(MODELS) });
    }
    if (request.method === "POST" && url.pathname === "/api/chat") return chat(request, env);
    return json({ error: "Not found" }, 404);
  }
};
